     1→"use client";
     2→
     3→import { useState } from "react";
     4→import { Card, CardContent, CardHeader } from "@/components/ui/card";
     5→import { Button } from "@/components/ui/button";
     6→import { Badge } from "@/components/ui/badge";
     7→import { Search, Play, Pause, Trash2, Clock } from "lucide-react";
     8→import {
     9→  deleteSavedSearchAction,
    10→  toggleSavedSearchAction,
    11→  applySavedSearchAction,
    12→} from "./saved-searches.action";
    13→import { useRouter } from "next/navigation";
    14→import { propertySearchSerializer } from "@/features/properties/search-params";
    15→import type { SavedSearch } from "@/generated/prisma";
    16→
    17→type SavedSearchCardProps = {
    18→  savedSearch: SavedSearch;
    19→  onUpdate: () => void;
    20→};
    21→
    22→export function SavedSearchCard({
    23→  savedSearch,
    24→  onUpdate,
    25→}: SavedSearchCardProps) {
    26→  const [isLoading, setIsLoading] = useState(false);
    27→  const router = useRouter();
    28→
    29→  const handleToggle = async () => {
    30→    setIsLoading(true);
    31→    try {
    32→      await toggleSavedSearchAction(savedSearch.id, !savedSearch.isActive);
    33→      onUpdate();
    34→    } catch (error) {
    35→      console.debug("Erreur lors de la mise à jour:", error);
    36→    } finally {
    37→      setIsLoading(false);
    38→    }
    39→  };
    40→
    41→  const handleDelete = async () => {
    42→    if (
    43→      !confirm(
    44→        `Êtes-vous sûr de vouloir supprimer la recherche "${savedSearch.name}" ?`,
    45→      )
    46→    ) {
    47→      return;
    48→    }
    49→
    50→    setIsLoading(true);
    51→    try {
    52→      await deleteSavedSearchAction(savedSearch.id);
    53→      onUpdate();
    54→    } catch (error) {
    55→      console.debug("Erreur lors de la suppression:", error);
    56→    } finally {
    57→      setIsLoading(false);
    58→    }
    59→  };
    60→
    61→  const handleApply = async () => {
    62→    setIsLoading(true);
    63→    try {
    64→      const search = await applySavedSearchAction(savedSearch.id);
    65→
    66→      // Build URL with filters - use current org path
    67→      console.debug("🔍 Applying saved search criteria:", search.criteria);
    68→
    69→      const searchParams = propertySearchSerializer(
    70→        search.criteria as Record<string, unknown>,
    71→      );
    72→
    73→      console.debug("🔗 Generated search params:", searchParams);
    74→
    75→      // Get current org from URL
    76→      const currentPath = window.location.pathname;
    77→      const orgMatch = currentPath.match(/\/orgs\/([^/]+)/);
    78→      const orgSlug = orgMatch ? orgMatch[1] : "";
    79→
    80→      const url = orgSlug
    81→        ? `/orgs/${orgSlug}/properties?${searchParams}`
    82→        : `/properties?${searchParams}`;
    83→
    84→      console.debug("🎯 Navigating to:", url);
    85→      router.push(url);
    86→    } catch (error) {
    87→      console.debug("❌ Erreur lors de l'application:", error);
    88→    } finally {
    89→      setIsLoading(false);
    90→    }
    91→  };
    92→
    93→  const criteria = savedSearch.criteria as Record<string, unknown>;
    94→
    95→  return (
    96→    <Card className="transition-shadow hover:shadow-md">
    97→      <CardHeader className="pb-3">
    98→        <div className="flex items-start justify-between">
    99→          <div className="min-w-0 flex-1 space-y-1">
   100→            <div className="flex items-center gap-2">
   101→              <h3 className="truncate font-semibold">{savedSearch.name}</h3>
   102→              <Badge
   103→                variant={savedSearch.isActive ? "default" : "secondary"}
   104→                className="flex-shrink-0 text-xs"
   105→              >
   106→                {savedSearch.isActive ? "Active" : "Inactive"}
   107→              </Badge>
   108→            </div>
   109→            <div className="text-muted-foreground flex items-center gap-4 text-xs">
   110→              <div className="flex items-center gap-1">
   111→                <Clock className="h-3 w-3" />
   112→                {savedSearch.frequency === "realtime"
   113→                  ? "Temps réel"
   114→                  : savedSearch.frequency === "daily"
   115→                    ? "Quotidien"
   116→                    : "Hebdomadaire"}
   117→              </div>
   118→              <div>
   119→                Créée le{" "}
   120→                {new Date(savedSearch.createdAt).toLocaleDateString("fr-FR")}
   121→              </div>
   122→            </div>
   123→          </div>
   124→        </div>
   125→      </CardHeader>
   126→
   127→      <CardContent className="space-y-4">
   128→        {/* Criteria preview */}
   129→        <div className="space-y-2">
   130→          <h4 className="text-sm font-medium">Critères de recherche :</h4>
   131→          <CriteriaPreview criteria={criteria} />
   132→        </div>
   133→
   134→        {/* Actions */}
   135→        <div className="flex items-center justify-between gap-2">
   136→          <Button
   137→            onClick={handleApply}
   138→            variant="outline"
   139→            size="sm"
   140→            disabled={isLoading}
   141→            className="flex-1"
   142→          >
   143→            <Search className="mr-1 h-3 w-3" />
   144→            Appliquer
   145→          </Button>
   146→
   147→          <div className="flex items-center gap-1">
   148→            <Button
   149→              onClick={handleToggle}
   150→              variant="ghost"
   151→              size="sm"
   152→              disabled={isLoading}
   153→              title={
   154→                savedSearch.isActive
   155→                  ? "Désactiver les alertes"
   156→                  : "Activer les alertes"
   157→              }
   158→            >
   159→              {savedSearch.isActive ? (
   160→                <Pause className="h-4 w-4" />
   161→              ) : (
   162→                <Play className="h-4 w-4" />
   163→              )}
   164→            </Button>
   165→
   166→            <Button
   167→              onClick={handleDelete}
   168→              variant="ghost"
   169→              size="sm"
   170→              disabled={isLoading}
   171→              title="Supprimer la recherche"
   172→              className="text-destructive hover:text-destructive"
   173→            >
   174→              <Trash2 className="h-4 w-4" />
   175→            </Button>
   176→          </div>
   177→        </div>
   178→      </CardContent>
   179→    </Card>
   180→  );
   181→}
   182→
   183→function CriteriaPreview({ criteria }: { criteria: Record<string, unknown> }) {
   184→  const items: string[] = [];
   185→
   186→  // Location
   187→  if (
   188→    criteria.selectedCitiesJson &&
   189→    typeof criteria.selectedCitiesJson === "string"
   190→  ) {
   191→    try {
   192→      const cities = JSON.parse(criteria.selectedCitiesJson);
   193→      if (cities.length > 0) {
   194→        items.push(`📍 ${cities.length} ville(s)`);
   195→      }
   196→    } catch {
   197→      // Ignore JSON parsing errors
   198→    }
   199→  } else if (criteria.city) {
   200→    items.push(`📍 ${criteria.city}`);
   201→  }
   202→
   203→  // Property types
   204→  if (
   205→    criteria.selectedCategoriesJson &&
   206→    typeof criteria.selectedCategoriesJson === "string"
   207→  ) {
   208→    try {
   209→      const categories = JSON.parse(criteria.selectedCategoriesJson);
   210→      if (categories.length > 0) {
   211→        const labels = categories.map((cat: string) => {
   212→          switch (cat) {
   213→            case "apartment":
   214→              return "Appt";
   215→            case "house":
   216→              return "Maison";
   217→            default:
   218→              return cat;
   219→          }
   220→        });
   221→        items.push(`🏠 ${labels.join(", ")}`);
   222→      }
   223→    } catch {
   224→      // Ignore JSON parsing errors
   225→    }
   226→  }
   227→
   228→  // Price
   229→  if (criteria.priceMin || criteria.priceMax) {
   230→    if (criteria.priceMin && criteria.priceMax) {
   231→      items.push(`💰 ${criteria.priceMin} - ${criteria.priceMax}€`);
   232→    } else if (criteria.priceMax) {
   233→      items.push(`💰 Max ${criteria.priceMax}€`);
   234→    } else if (criteria.priceMin) {
   235→      items.push(`💰 Min ${criteria.priceMin}€`);
   236→    }
   237→  }
   238→
   239→  // Surface
   240→  if (criteria.surfaceMin || criteria.surfaceMax) {
   241→    if (criteria.surfaceMin && criteria.surfaceMax) {
   242→      items.push(`📐 ${criteria.surfaceMin} - ${criteria.surfaceMax}m²`);
   243→    } else if (criteria.surfaceMax) {
   244→      items.push(`📐 Max ${criteria.surfaceMax}m²`);
   245→    } else if (criteria.surfaceMin) {
   246→      items.push(`📐 Min ${criteria.surfaceMin}m²`);
   247→    }
   248→  }
   249→
   250→  // Rooms
   251→  if (criteria.rooms && criteria.rooms !== "all") {
   252→    items.push(`🚪 ${criteria.rooms}+ pièces`);
   253→  }
   254→
   255→  if (items.length === 0) {
   256→    return (
   257→      <p className="text-muted-foreground text-xs">
   258→        Recherche générale (tous types de biens)
   259→      </p>
   260→    );
   261→  }
   262→
   263→  return (
   264→    <div className="flex flex-wrap gap-1">
   265→      {items.map((item, index) => (
   266→        <Badge key={index} variant="secondary" className="text-xs">
   267→          {item}
   268→        </Badge>
   269→      ))}
   270→    </div>
   271→  );
   272→}
   273→

