     1→"use client";
     2→
     3→import { useEffect, useState } from "react";
     4→import { SavedSearchCard } from "./saved-search-card";
     5→import { getSavedSearchesAction } from "./saved-searches.action";
     6→import { Search, Plus } from "lucide-react";
     7→import { Button } from "@/components/ui/button";
     8→import Link from "next/link";
     9→import type { SavedSearch } from "@/generated/prisma";
    10→
    11→export function SavedSearchesList() {
    12→  const [savedSearches, setSavedSearches] = useState<SavedSearch[]>([]);
    13→  const [isLoading, setIsLoading] = useState(true);
    14→
    15→  const loadSavedSearches = async () => {
    16→    try {
    17→      const searches = await getSavedSearchesAction();
    18→      setSavedSearches(searches);
    19→    } catch (error) {
    20→      console.debug("Erreur lors du chargement des recherches:", error);
    21→    } finally {
    22→      setIsLoading(false);
    23→    }
    24→  };
    25→
    26→  useEffect(() => {
    27→    void loadSavedSearches();
    28→  }, []);
    29→
    30→  if (isLoading) {
    31→    return (
    32→      <div className="space-y-4">
    33→        {[...Array(3)].map((_, index) => (
    34→          <div key={index} className="bg-muted h-32 animate-pulse rounded-lg" />
    35→        ))}
    36→      </div>
    37→    );
    38→  }
    39→
    40→  if (savedSearches.length === 0) {
    41→    return (
    42→      <div className="flex min-h-[400px] flex-col items-center justify-center text-center">
    43→        <Search className="text-muted-foreground mb-4 size-16" />
    44→        <h3 className="mb-2 text-lg font-semibold">
    45→          Aucune recherche sauvegardée
    46→        </h3>
    47→        <p className="text-muted-foreground mb-6 max-w-md">
    48→          Créez votre première recherche sauvegardée pour recevoir des alertes
    49→          sur les nouveaux biens qui correspondent à vos critères.
    50→        </p>
    51→        <Link href="/properties">
    52→          <Button>
    53→            <Plus className="mr-2 h-4 w-4" />
    54→            Créer une recherche
    55→          </Button>
    56→        </Link>
    57→      </div>
    58→    );
    59→  }
    60→
    61→  const activeSearches = savedSearches.filter((search) => search.isActive);
    62→  const inactiveSearches = savedSearches.filter((search) => !search.isActive);
    63→
    64→  return (
    65→    <div className="space-y-6">
    66→      {/* Stats */}
    67→      <div className="text-muted-foreground flex items-center gap-4 text-sm">
    68→        <span>{savedSearches.length} recherche(s) sauvegardée(s)</span>
    69→        <span>•</span>
    70→        <span>{activeSearches.length} active(s)</span>
    71→      </div>
    72→
    73→      {/* Active searches */}
    74→      {activeSearches.length > 0 && (
    75→        <div className="space-y-4">
    76→          <h3 className="text-lg font-semibold">Recherches actives</h3>
    77→          <div className="grid gap-4">
    78→            {activeSearches.map((search) => (
    79→              <SavedSearchCard
    80→                key={search.id}
    81→                savedSearch={search}
    82→                onUpdate={loadSavedSearches}
    83→              />
    84→            ))}
    85→          </div>
    86→        </div>
    87→      )}
    88→
    89→      {/* Inactive searches */}
    90→      {inactiveSearches.length > 0 && (
    91→        <div className="space-y-4">
    92→          <h3 className="text-muted-foreground text-lg font-semibold">
    93→            Recherches inactives
    94→          </h3>
    95→          <div className="grid gap-4">
    96→            {inactiveSearches.map((search) => (
    97→              <SavedSearchCard
    98→                key={search.id}
    99→                savedSearch={search}
   100→                onUpdate={loadSavedSearches}
   101→              />
   102→            ))}
   103→          </div>
   104→        </div>
   105→      )}
   106→
   107→      {/* Call to action */}
   108→      <div className="border-t pt-6">
   109→        <Link href="/properties">
   110→          <Button variant="outline" className="w-full">
   111→            <Plus className="mr-2 h-4 w-4" />
   112→            Créer une nouvelle recherche
   113→          </Button>
   114→        </Link>
   115→      </div>
   116→    </div>
   117→  );
   118→}
