     1→"use client";
     2→
     3→import { useState } from "react";
     4→import { Button } from "@/components/ui/button";
     5→import { Save } from "lucide-react";
     6→import { SaveSearchDialog } from "./save-search-dialog";
     7→import { createSavedSearchAction } from "./saved-searches.action";
     8→import type { PropertySearchFilters } from "@/features/properties/types";
     9→
    10→type SaveSearchButtonProps = {
    11→  filters: PropertySearchFilters;
    12→  variant?: "default" | "outline" | "ghost";
    13→  size?: "default" | "sm" | "lg";
    14→  className?: string;
    15→};
    16→
    17→export function SaveSearchButton({
    18→  filters,
    19→  variant = "outline",
    20→  size = "sm",
    21→  className,
    22→}: SaveSearchButtonProps) {
    23→  const [isDialogOpen, setIsDialogOpen] = useState(false);
    24→  const [isLoading, setIsLoading] = useState(false);
    25→
    26→  const handleSaveSearch = async (name: string) => {
    27→    setIsLoading(true);
    28→    try {
    29→      await createSavedSearchAction({
    30→        name,
    31→        criteria: filters,
    32→        isActive: true,
    33→        frequency: "daily",
    34→      });
    35→      setIsDialogOpen(false);
    36→      // TODO: Show success toast
    37→    } catch (error) {
    38→      console.debug("Erreur lors de la sauvegarde:", error);
    39→      // TODO: Show error toast
    40→    } finally {
    41→      setIsLoading(false);
    42→    }
    43→  };
    44→
    45→  // Check if there are any active filters worth saving
    46→  const hasActiveFilters = Object.entries(filters).some(([key, value]) => {
    47→    if (
    48→      key === "page" ||
    49→      key === "sortBy" ||
    50→      key === "sortOrder" ||
    51→      key === "view"
    52→    ) {
    53→      return false;
    54→    }
    55→    if (typeof value === "string" && value.trim() === "") {
    56→      return false;
    57→    }
    58→    if (typeof value === "boolean" && !value) {
    59→      return false;
    60→    }
    61→    return true;
    62→  });
    63→
    64→  if (!hasActiveFilters) {
    65→    return null; // Don't show button if no filters are active
    66→  }
    67→
    68→  return (
    69→    <>
    70→      <Button
    71→        variant={variant}
    72→        size={size}
    73→        onClick={() => setIsDialogOpen(true)}
    74→        className={className}
    75→      >
    76→        <Save className="mr-1 h-3 w-3" />
    77→        <span className="xs:inline hidden">Sauvegarder</span>
    78→        <span className="xs:hidden">Save</span>
    79→      </Button>
    80→
    81→      <SaveSearchDialog
    82→        open={isDialogOpen}
    83→        onOpenChange={setIsDialogOpen}
    84→        onSave={handleSaveSearch}
    85→        isLoading={isLoading}
    86→        filters={filters}
    87→      />
    88→    </>
    89→  );
    90→}
    91→

