     1→"use client";
     2→
     3→import { useState, useEffect } from "react";
     4→import { Button } from "@/components/ui/button";
     5→import { Plus, Bell } from "lucide-react";
     6→import { AlertCard } from "./alert-card";
     7→import { CreateAlertDialog } from "./create-alert-dialog";
     8→import type { PropertyAlert, CreateAlertRequest } from "./types";
     9→import {
    10→  createAlertAction,
    11→  deleteAlertAction,
    12→  toggleAlertAction,
    13→  getAlertsAction,
    14→} from "./alerts.action";
    15→
    16→export function AlertsList() {
    17→  const [alerts, setAlerts] = useState<PropertyAlert[]>([]);
    18→  const [isCreateDialogOpen, setIsCreateDialogOpen] = useState(false);
    19→  const [isLoading, setIsLoading] = useState(false);
    20→  const [isInitialLoading, setIsInitialLoading] = useState(true);
    21→
    22→  // Load alerts on component mount
    23→  useEffect(() => {
    24→    const loadAlerts = async () => {
    25→      try {
    26→        const userAlerts = await getAlertsAction();
    27→        setAlerts(userAlerts);
    28→      } catch (error) {
    29→        console.debug("Failed to load alerts:", error);
    30→      } finally {
    31→        setIsInitialLoading(false);
    32→      }
    33→    };
    34→
    35→    void loadAlerts();
    36→  }, []);
    37→
    38→  const handleCreateAlert = async (request: CreateAlertRequest) => {
    39→    setIsLoading(true);
    40→    try {
    41→      const newAlert = await createAlertAction(request);
    42→      setAlerts((prev) => [...prev, newAlert]);
    43→    } catch (error) {
    44→      console.debug("Failed to create alert:", error);
    45→      // TODO: Show error toast
    46→    } finally {
    47→      setIsLoading(false);
    48→    }
    49→  };
    50→
    51→  const handleToggleActive = async (alertId: string, isActive: boolean) => {
    52→    try {
    53→      const updatedAlert = await toggleAlertAction(alertId, isActive);
    54→      setAlerts((prev) =>
    55→        prev.map((alert) => (alert.id === alertId ? updatedAlert : alert)),
    56→      );
    57→    } catch (error) {
    58→      console.debug("Failed to toggle alert:", error);
    59→      // TODO: Show error toast
    60→    }
    61→  };
    62→
    63→  const handleDeleteAlert = async (alertId: string) => {
    64→    try {
    65→      await deleteAlertAction(alertId);
    66→      setAlerts((prev) => prev.filter((alert) => alert.id !== alertId));
    67→    } catch (error) {
    68→      console.debug("Failed to delete alert:", error);
    69→      // TODO: Show error toast
    70→    }
    71→  };
    72→
    73→  if (isInitialLoading) {
    74→    return (
    75→      <div className="space-y-4">
    76→        <div className="flex items-center justify-between">
    77→          <div className="bg-muted h-8 w-48 animate-pulse rounded" />
    78→          <div className="bg-muted h-10 w-32 animate-pulse rounded" />
    79→        </div>
    80→        <div className="space-y-4">
    81→          {Array.from({ length: 3 }).map((_, i) => (
    82→            <div key={i} className="bg-muted h-48 animate-pulse rounded-lg" />
    83→          ))}
    84→        </div>
    85→      </div>
    86→    );
    87→  }
    88→
    89→  return (
    90→    <div className="space-y-6">
    91→      <div className="flex items-center justify-between">
    92→        <div>
    93→          <h2 className="text-2xl font-bold">Mes alertes</h2>
    94→          <p className="text-muted-foreground">
    95→            Recevez des notifications quand de nouveaux biens correspondent à
    96→            vos critères
    97→          </p>
    98→        </div>
    99→        <Button onClick={() => setIsCreateDialogOpen(true)}>
   100→          <Plus className="mr-2 h-4 w-4" />
   101→          Nouvelle alerte
   102→        </Button>
   103→      </div>
   104→
   105→      {alerts.length === 0 ? (
   106→        <div className="flex min-h-[400px] flex-col items-center justify-center text-center">
   107→          <Bell className="text-muted-foreground mb-4 size-16" />
   108→          <h3 className="mb-2 text-xl font-semibold">
   109→            Aucune alerte configurée
   110→          </h3>
   111→          <p className="text-muted-foreground mb-6 max-w-md">
   112→            Créez votre première alerte pour être notifié quand de nouveaux
   113→            biens correspondent à vos critères de recherche.
   114→          </p>
   115→          <Button onClick={() => setIsCreateDialogOpen(true)}>
   116→            <Plus className="mr-2 h-4 w-4" />
   117→            Créer ma première alerte
   118→          </Button>
   119→        </div>
   120→      ) : (
   121→        <div className="grid gap-4">
   122→          {alerts.map((alert) => (
   123→            <AlertCard
   124→              key={alert.id}
   125→              alert={alert}
   126→              onToggleActive={handleToggleActive}
   127→              onDelete={handleDeleteAlert}
   128→            />
   129→          ))}
   130→        </div>
   131→      )}
   132→
   133→      <CreateAlertDialog
   134→        open={isCreateDialogOpen}
   135→        onOpenChange={setIsCreateDialogOpen}
   136→        onCreateAlert={handleCreateAlert}
