   177→export async function updateFavoriteAction(request: UpdateFavoriteRequest) {
   178→  const session = await auth.api.getSession({
   179→    headers: await headers(),
   180→  });
   181→
   182→  if (!session?.user.id) {
   183→    redirect("/auth/signin");
   184→  }
   185→
   186→  const favorite = await prisma.favorite.findFirst({
   187→    where: {
   188→      id: request.id,
   189→      userId: session.user.id,
   190→    },
   191→  });
   192→
   193→  if (!favorite) {
   194→    throw new Error("Favori non trouvé");
   195→  }
   196→
   197→  const updatedFavorite = await prisma.favorite.update({
   198→    where: {
   199→      id: request.id,
   200→    },
   201→    data: {
   202→      ...(request.notes !== undefined && { notes: request.notes }),
   203→      ...(request.status && { status: request.status }),
   204→      ...(request.priority && { priority: request.priority }),
   205→    },
   206→    include: {
   207→      property: true,
   208→    },
   209→  });
   210→
   211→  console.debug(
   212→    `✅ [Favorites] Updated favorite ${request.id} for user ${session.user.id}`,
   213→  );
   214→
   215→  revalidatePath("/favorites");
   216→
   217→  return updatedFavorite;
   218→}
