   296→
   297→  if (existingFavorite) {
   298→    // Remove from favorites
   299→    await deleteFavoriteAction(existingFavorite.id);
   300→    return { isFavorite: false };
   301→  } else {
   302→    // Add to favorites
   303→    await createFavoriteAction({ propertyId: propertyExternalId });
   304→    return { isFavorite: true };
   305→  }
   306→}
