export async function createFavoriteAction(request: CreateFavoriteRequest) {
  console.debug(
    "🔍 [Favorites] Creating favorite for property:",
    request.propertyId,
  );

  const session = await auth.api.getSession({
    headers: await headers(),
  });

  if (!session?.user.id) {
    redirect("/auth/signin");
  }

  console.debug("🔍 [Favorites] User ID:", session.user.id);

  // Check if property exists, if not create it
  let property = await prisma.property.findUnique({
    where: { externalId: request.propertyId },
  });

  console.debug("🔍 [Favorites] Property exists:", property ? "YES" : "NO");

  if (!property) {
    try {
      console.debug("🔍 [Favorites] Creating new property in database...");
      console.debug(
        "🔍 [Favorites] Fetching property data from MoteurImmo API...",
      );

      // Récupérer les vraies données du bien via MoteurImmo API
      const moteurImmoProperty = await moteurImmoClient.getListingById(
        request.propertyId,
      );
      console.debug(
        "✅ [Favorites] Property data fetched from MoteurImmo:",
        moteurImmoProperty.title,
      );

      property = await prisma.property.create({
        data: {
          externalId: request.propertyId,
          title: moteurImmoProperty.title,
          description: moteurImmoProperty.description,
          type: moteurImmoProperty.type,
          category: moteurImmoProperty.category,
          price: moteurImmoProperty.price,
          surface: moteurImmoProperty.surface,
          rooms: moteurImmoProperty.rooms,
          bedrooms: moteurImmoProperty.bedrooms,
          floor: moteurImmoProperty.floor,
          totalFloors: moteurImmoProperty.totalFloors,
          address: moteurImmoProperty.address ?? "",
          city: moteurImmoProperty.city,
          postalCode: moteurImmoProperty.postalCode ?? "",
          department: "", // Required by Prisma schema
          region: "", // Required by Prisma schema
          energyClass: moteurImmoProperty.energyClass,
          hasGarden: moteurImmoProperty.hasGarden,
          hasParking: moteurImmoProperty.hasParking,
          hasLift: moteurImmoProperty.hasLift,
          hasTerrace: moteurImmoProperty.hasTerrace,
          hasBalcony: moteurImmoProperty.hasBalcony,
          sourceUrl: moteurImmoProperty.url,
          sourceId: moteurImmoProperty.origin,
          publishedAt: new Date(moteurImmoProperty.publishedAt),
        },
      });
      console.debug("✅ [Favorites] Property created with ID:", property.id);
    } catch (error) {
      console.debug("❌ [Favorites] Error creating property:", error);
      // Si l'API MoteurImmo échoue, créer un placeholder comme avant
      console.debug(
        "🔍 [Favorites] Fallback: Creating placeholder property...",
      );
      property = await prisma.property.create({
        data: {
          externalId: request.propertyId,
          title: "Bien immobilier - Données en cours de chargement",
          type: "sale",
          category: "flat",
          price: 0,
          address: "Adresse en cours de chargement...",
          city: "Ville inconnue",
          postalCode: "00000",
          department: "Département",
          region: "Région",
          publishedAt: new Date(),
        },
      });
    }
  }

  // Check if already in favorites
  const existingFavorite = await prisma.favorite.findUnique({
    where: {
      userId_propertyId: {
        userId: session.user.id,
        propertyId: property.id,
      },
    },
  });

  if (existingFavorite) {
    throw new Error("Ce bien est déjà dans vos favoris");
  }

  const favorite = await prisma.favorite.create({
    data: {
      userId: session.user.id,
      propertyId: property.id,
      notes: request.notes,
      priority: request.priority ?? "medium",
    },
    include: {
      property: true,
    },
  });

  console.debug(
    `✅ [Favorites] Added property ${property.id} to favorites for user ${session.user.id}`,
  );

  revalidatePath("/favorites");
  revalidatePath("/properties");
  revalidatePath("/orgs", "layout");

  return favorite;
}

